// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Table } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Data/Table)

figma.connect(Table, FIGMA_NODE_URL, {
  props: {
    density: figma.enum('density', { 'comfortable': 'comfortable', 'compact': 'compact' }),
    zebra: figma.boolean('zebra'),
    stickyHeader: figma.boolean('stickyHeader'),
    isLoading: figma.boolean('isLoading'),
  },
  example: ({ density, zebra, stickyHeader, isLoading }) => (
    <Table density={density} zebra={zebra} stickyHeader={stickyHeader} isLoading={isLoading}></Table>
  ),
});
